grid = [
[5,5,0,0,0,5,0,5,5,5,5,5,5,5,5,5],
[0,0,5,5,5,5,0,5,5,0,5,5,5,5,5,5],
]+[[0]*16 for _ in range(15)]+[
[5,5,0,0,0,5,0,5,5,5,5,0,0,0,0,0],
[0,0,5,5,5,5,0,5,5,0,5,0,0,0,0,0],
]+[[0]*16 for _ in range(3)]
h,w=len(grid),len(grid[0])
out=[r[:] for r in grid]
for r in range(h):
    inds=[c for c,v in enumerate(grid[r]) if v==5]
    if len(inds)>=2:
        for c in range(min(inds)+1,max(inds)):
            if out[r][c]==0: out[r][c]=3
for c in range(w):
    inds=[r for r in range(h) if grid[r][c]==5]
    if len(inds)>=2:
        for r in range(min(inds)+1,max(inds)):
            if out[r][c]==0: out[r][c]=3
print(len(out), [len(r) for r in out])
print('\n'.join('['+', '.join(map(str,r))+'],' for r in out))

